<script src="{{ asset('js/datas.js') }}"></script><script>
const minimos={introducao:800,atividades:1200,conclusao:600}, maximos={introducao:2500,atividades:2200,conclusao:2000}, ids=Object.keys(minimos);
function contar(texto){return Array.from(texto.replace(/[\s\p{Z}]+/gu,' ').trim()).length;}
function atualizar(){let completos=0;for(const id of ids){const el=document.getElementById(id), nome=id[0].toUpperCase()+id.slice(1), minimo=minimos[id], maximo=maximos[id], quantidade=contar(el.value), total=Array.from(el.value.trim()).length, faltam=Math.max(0,minimo-quantidade), excesso=Math.max(0,total-maximo), status=document.getElementById('cont'+nome);if(!faltam&&!excesso)completos++;status.textContent=quantidade+' caracteres úteis (mínimo '+minimo+'); '+total+' caracteres (máximo '+maximo+'). '+(excesso?'Reduza '+excesso+' caracteres.':faltam?'Faltam '+faltam+' caracteres úteis.':'Dentro dos limites.');status.className='muted campo-status '+(faltam||excesso?'incompleto':'completo');document.getElementById('preenchimento'+nome).style.width=Math.min(100,quantidade/minimo*100)+'%';document.getElementById('barra'+nome).setAttribute('aria-valuenow',Math.min(quantidade,minimo));}document.getElementById('progresso').style.width=(completos/3*100)+'%';document.getElementById('progressoTexto').textContent=completos+' de 3 partes dentro dos limites';return completos===3;}
ids.forEach(id=>document.getElementById(id).addEventListener('input',atualizar));atualizar();
const form=document.getElementById('formRelatorio'), statusEl=document.getElementById('saveStatus'), version=document.getElementById('versao');
let dirty=false, pending=null, timer=null, blocked=false;
function modified(){dirty=true;statusEl.textContent='Alterações pendentes…';clearTimeout(timer);if(!blocked)timer=setTimeout(()=>save().catch(()=>{}),1200);}
form.querySelectorAll('textarea,input:not([type=hidden])').forEach(el=>el.addEventListener('input',modified));
async function save(concluir=false){
    clearTimeout(timer);
    if(pending){await pending;return save(concluir);}
    if(blocked)throw new Error('Copie seu texto e recarregue a página para continuar.');
    if(!dirty&&!concluir)return;
    const invalidDate=form.querySelector('input[data-data-manual]:invalid');
    if(invalidDate){statusEl.textContent='Informe uma data válida no formato DD/MM/AAAA.';throw new Error(statusEl.textContent);}
    const data=new FormData(form);if(concluir)data.set('concluir','1');
    dirty=false;statusEl.textContent='Salvando…';
    pending=(async()=>{
        try{
            const response=await fetch(form.action,{method:'POST',body:data,headers:{Accept:'application/json'},credentials:'same-origin'});
            if(!response.ok){
                if(response.status===409)blocked=true;
                let message=response.status===409?'Outra aba alterou este relatório. Copie seus textos e recarregue a página.':'Não foi possível salvar. Mantenha esta página aberta e tente novamente.';
                if(response.status===422){const error=await response.json();message=Object.values(error.errors||{}).flat().join(' ');}
                throw new Error(message);
            }
            const result=await response.json();version.value=result.versao;
            statusEl.textContent=result.concluido?'Relatório concluído.':('Salvo com sucesso às '+new Date(result.salvo_em).toLocaleTimeString('pt-BR'));
        }catch(error){dirty=true;const message=error instanceof TypeError?'Não foi possível conectar ao servidor. Mantenha esta página aberta e tente salvar novamente.':error.message;statusEl.textContent=message;throw new Error(message);}
        finally{pending=null;}
    })();
    await pending;
    if(dirty&&!blocked)return save();
}
form.addEventListener('submit',e=>{e.preventDefault();dirty=true;save().catch(()=>{});});
document.getElementById('concluir').addEventListener('click',()=>{if(!atualizar()){statusEl.textContent='Confira os mínimos e máximos de caracteres antes de finalizar. Você pode salvar como rascunho.';return;}save(true).catch(()=>{});});
document.getElementById('pdfLink').addEventListener('click',async e=>{e.preventDefault();if(!atualizar()){statusEl.textContent='Confira os mínimos e máximos de caracteres antes de gerar o PDF definitivo.';return;}try{await save();window.location.assign(document.getElementById('pdfLink').href);}catch{}});
document.getElementById('previewLink').addEventListener('click',async e=>{e.preventDefault();try{await save();window.location.assign(document.getElementById('previewLink').href);}catch{}});
window.addEventListener('beforeunload',e=>{if(dirty||pending){e.preventDefault();e.returnValue='';}});
window.addEventListener('online',()=>{if(dirty&&!blocked)save().catch(()=>{});});
</script></main></body></html>
